const priorityData = $input.all(); // Data from the Classifier LLM
const rawArticles = $('Select important fields').all(); // Your raw news content

const grouped = {};

// 1. Filter and Match
rawArticles.forEach(article => {
  const match = priorityData.find(p => p.json.output.id === article.json.url);

  // 2. Only proceed if priority is high (e.g., > 7)
  if (match && match.json.output.priority > 7) {
    const category = match.json.output.category;

    // 3. Group by Category
    if (!grouped[category]) {
      grouped[category] = {
        category: category,
        articles: []
      };
    }

    // Add the article and its AI-generated priority to the group
    grouped[category].articles.push({
      ...article.json,
      priority: match.json.output.priority,
      is_breaking: match.json.output.is_breaking
    });
  }
});

// Return as an array of groups for the "Split in Batches" or "Loop" node
return Object.values(grouped);
